insert into public.grammar_points (hsk_level, title, explanation, examples, order_idx)
values
  (1, 'Basic word order (SVO)', 'Chinese follows a Subject-Verb-Object word order, similar to English. The subject comes first, followed by the verb, and then the object.', '[{"zh":"我喝茶。","pinyin":"Wǒ hē chá.","en":"I drink tea."},{"zh":"她看书。","pinyin":"Tā kàn shū.","en":"She reads books."},{"zh":"他吃饭。","pinyin":"Tā chī fàn.","en":"He eats food."}]'::jsonb, 1),
  (1, 'Questions with 吗 (ma)', 'To turn a statement into a yes/no question, add 吗 (ma) at the end. The word order stays the same.', '[{"zh":"你好吗？","pinyin":"Nǐ hǎo ma?","en":"How are you?"},{"zh":"你是学生吗？","pinyin":"Nǐ shì xuéshēng ma?","en":"Are you a student?"},{"zh":"他喜欢中国吗？","pinyin":"Tā xǐhuān Zhōngguó ma?","en":"Does he like China?"}]'::jsonb, 2),
  (1, 'Negation with 不 (bù)', 'Place 不 (bù) before a verb or adjective to negate it. Note: 有 (yǒu) uses 没 (méi) for negation instead.', '[{"zh":"我不喝咖啡。","pinyin":"Wǒ bù hē kāfēi.","en":"I don''t drink coffee."},{"zh":"她不是老师。","pinyin":"Tā bú shì lǎoshī.","en":"She is not a teacher."},{"zh":"我没有钱。","pinyin":"Wǒ méiyǒu qián.","en":"I don''t have money."}]'::jsonb, 3),
  (2, '了 (le) for completed actions', 'Place 了 (le) after a verb to indicate a completed action. It does not directly translate to past tense - it marks completion.', '[{"zh":"我吃了午饭。","pinyin":"Wǒ chī le wǔfàn.","en":"I ate lunch."},{"zh":"她买了一本书。","pinyin":"Tā mǎi le yì běn shū.","en":"She bought a book."},{"zh":"我们看了电影。","pinyin":"Wǒmen kàn le diànyǐng.","en":"We watched a movie."}]'::jsonb, 1),
  (2, '因为...所以... (because...therefore...)', 'Use 因为 (yīnwèi) to state the cause and 所以 (suǒyǐ) to state the result. You can use both together or just one.', '[{"zh":"因为下雨，所以我没去。","pinyin":"Yīnwèi xià yǔ, suǒyǐ wǒ méi qù.","en":"Because it rained, I didn''t go."},{"zh":"因为他生病了，所以没来上课。","pinyin":"Yīnwèi tā shēngbìng le, suǒyǐ méi lái shàngkè.","en":"Because he was sick, he didn''t come to class."}]'::jsonb, 2),
  (3, '把 (bǎ) construction', 'The 把 (bǎ) structure is used to emphasize the result or effect of an action on a specific object. Pattern: Subject + 把 + Object + Verb + Complement.', '[{"zh":"请把门关上。","pinyin":"Qǐng bǎ mén guān shàng.","en":"Please close the door."},{"zh":"他把作业做完了。","pinyin":"Tā bǎ zuòyè zuò wán le.","en":"He finished his homework."},{"zh":"我把书放在桌子上了。","pinyin":"Wǒ bǎ shū fàng zài zhuōzi shàng le.","en":"I put the book on the table."}]'::jsonb, 1)
insert into public.generated_exercises (type, hsk_level, prompt, answer, source_model, created_by)
